    mapp={'tl':'bl','tr':'tl','bl':'br','br':'tr'}
    # assign markers to blocks: each marker -> nearest block by chebyshev-ish distance to nearest corner
    mk=[]
    for r in range(h):
        for c in range(w):
            if g[r][c]:
                best=None
                for a,b in blks:
                    d=min(abs(a-r)+abs(b-c), abs(a+1-r)+abs(b-1-c), abs(a-r)+abs(b+1-c), abs(a+1-r)+abs(b+1-c))
                    cand=(d,(a,b))
