                a,b=best[1]
                qn='t' if r<=a+1 else 'b'+'l' if c<b+1 else 'r'   # placeholder, fix below
                mk.append(((a,b),qn,(r,c),g[r][c]))
    # proper quadrant determination: marker in quadrant q iff walking from corner a+dq in dq hits marker
    res={}
    for a,b in blks:
