def f(g):
    H,W=len(g),len(g[0])
    blocks=[]
    seen=set()
    for r in range(H-1):
        for c in range(W-1):
            if g[r][c]==2 and g[r+1][c]==2 and g[r][c+1]==2 and g[r+1][c+1]==2:
                blocks.append((r,c)); seen.add((r,c)); seen.add((r,c+1)); seen.add((r+1,c)); seen.add((r+1,c+1))
    dirs={'TL':(-1,1),'TR':(1,1),'BR':(1,-1),'BL':(-1,-1)}  # outward from corner
    corr={}  # corner name -> (dr,dc) outward from block center
    out=[r[:] for r in g]
    corners=[('TL','TR'),('BR','BL')]  # clockwise: TL,TR,BR,BL
    corner_dirs={'TL':(-1,1),'TR':(1,1),'BR':(1,-1),'BL':(-1,-1)}
    for br,bc in blocks:
        brows=range(br,br+2); bcols=range(bc,bc+2)
        seeds={}
        for cn,dv in corner_dirs.items():
            dr,dc=dv; cells=[]
            rr,cc=br+(dr//2)+dr*(0), bc+(dc//2)+dc*0
            # start just beyond corner
            rr,cc=br+dr* (1 if dv[0]>=0 else -1)+ (0 if abs(dv[0])==0 else 0), None
            # simpler: step from corner
            rr,cc=br+dv[0],bc+dv[1]
            while 0<=rr<H and 0<=cc<W:
                if g[rr][cc]!=0 and (rr,cc) not in seen:
                    seeds[cn]=g[rr][cc]; break
                rr+=dv[0]; cc+=dv[1]
        # collect all seeds into one rotation sequence
        if not seeds: continue
        return None
    return out

