            if g[r][c]==2 and g[r+1][c]==2 and g[r][c+1]==2 and g[r+1][c+1]==2]
    seen=set()
    for br,bc in blocks:
        for x in (br,br+1):
            for y in (bc,bc+1):
                seen.add((x,y))
    cor_order=['TL','TR','BR','BL']
    dirs={'TL':(-1,-1),'TR':(-1,1),'BR':(1,1),'BL':(1,-1)}
