            while 0<=rr<H and 0<=cc<W and (rr,cc) not in seen and g[rr][cc]==0:
                rr+=dr; cc+=dc
            if 0<=rr<H and 0<=cc<W and (rr,cc) not in seen and g[rr][cc]!=0:
                seeds[cn]=g[rr][cc]; out[rr][cc]=seeds[cn]
        seq=[seeds.get(cn) for cn in cor_order]
