                    col=I[r][c]; st=[(r,c)]; seen.add((r,c)); cells=[]
                    while st:
                        x,y=st.pop(); cells.append((x,y))
                        for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                            nx,ny=x+dx,y+dy
                            if 0<=nx<h and 0<=ny<w and (nx,ny) not in seen and I[nx][ny]==col:
